package com.example.demo.config;
import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.components.*;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI api(){return new OpenAPI().info(new Info().title("API онлайн-аптеки").version("1.0").description("REST API для каталога, заказов и администрирования. Защищённые методы используют JWT.")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
